using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;
using Autodesk.Revit.DB;
namespace Autodesk.Revit.DB {
 public enum BuiltInCategory { OST_Walls=-2000011, OST_Floors=-2000032 }
 public enum StorageType { Double,Integer,String,ElementId }
 public class ElementId { public long Value;public ElementId(long x){Value=x;} }
 public class Category { public ElementId Id;public static Category GetCategory(Document d,BuiltInCategory c){return new Category{Id=new ElementId((long)c)};} }
 public class Definition { public string DataType="text"; }
 public class Parameter { public ElementId Id;public Element Element;public bool IsReadOnly,HasValue=true;public StorageType StorageType;public object Value;public Definition Definition=new Definition(); }
 public class Element { public ElementId Id,LevelId,TypeId;public string UniqueId;public bool IsValidObject=true;public Document Document;public Category Category;public List<Parameter> Parameters=new List<Parameter>();public ElementId GetTypeId(){return TypeId;} }
 public class ElementType:Element {} public class Level:Element {}
 public class Document { public bool IsValidObject=true,IsFamilyDocument,IsLinked;public string PathName="D:\\fixture.rvt";public Dictionary<long,Element> Elements=new Dictionary<long,Element>(); public Action OnRegenerate,OnWrite; public bool FailRollback; public void Regenerate(){if(OnRegenerate!=null)OnRegenerate();} }
 public enum TransactionStatus { Started, Committed, RolledBack }
 public class TransactionGroup:IDisposable { Document d; Dictionary<Parameter,object> before=new Dictionary<Parameter,object>(); TransactionStatus state; public TransactionGroup(Document doc,string name){d=doc;} public TransactionStatus Start(){foreach(var e in d.Elements.Values)foreach(var p in e.Parameters)before[p]=p.Value;return state=TransactionStatus.Started;} public TransactionStatus GetStatus(){return state;} public TransactionStatus RollBack(){if(d.FailRollback)throw new InvalidOperationException("rollback unconfirmed");foreach(var p in before)p.Key.Value=p.Value;return state=TransactionStatus.RolledBack;} public TransactionStatus Assimilate(){return state=TransactionStatus.Committed;} public void Dispose(){} }
 public class Transaction:IDisposable { TransactionStatus state;public Transaction(Document d,string name){} public TransactionStatus Start(){return state=TransactionStatus.Started;} public TransactionStatus GetStatus(){return state;} public TransactionStatus Commit(){return state=TransactionStatus.Committed;} public TransactionStatus RollBack(){return state=TransactionStatus.RolledBack;} public void Dispose(){} }
 public class FilteredElementCollector:IDisposable,IEnumerable<Element> { Document d;BuiltInCategory category;public FilteredElementCollector(Document d){this.d=d;}public FilteredElementCollector OfCategory(BuiltInCategory c){category=c;return this;}public FilteredElementCollector WhereElementIsNotElementType(){return this;}public IEnumerator<Element> GetEnumerator(){return d.Elements.Values.Where(e=>!(e is ElementType)&&e.Category!=null&&e.Category.Id.Value==(long)category).GetEnumerator();}IEnumerator IEnumerable.GetEnumerator(){return GetEnumerator();}public void Dispose(){} }
}
namespace RevitLocalCodex {
 internal static class NativeModelQueries { internal class ReadBudget { public int Scanned;public ReadBudget(int max){}public void Scan(){if(++Scanned>20000)throw new InvalidOperationException("scan budget");}public void Reserve(object o){} }public static string SignedId(ElementId id){return id.Value.ToString();} }
 internal static partial class WorkbenchActions {
  static Element RequiredElement(Document d,long id){Element e;if(!d.Elements.TryGetValue(id,out e))throw new InvalidOperationException("missing");return e;}
  static Parameter ResolveInstanceParameter(Document d,long id,long pid,out Element owner){owner=RequiredElement(d,id);var matches=owner.Parameters.Where(x=>x.Id.Value==pid).ToArray();if(matches.Length!=1||matches[0].IsReadOnly||!Object.ReferenceEquals(matches[0].Element,owner))throw new InvalidOperationException("owner or parameter");return matches[0];}
  static object InternalValue(Parameter p){return p.HasValue?p.Value:null;}
  static string ParameterDataType(Parameter p){return p.Definition.DataType;}
  static object NormalizeParameterValue(Parameter p,object value,string name,bool required){if(p.StorageType!=StorageType.String || !(value is string))throw new InvalidOperationException("invalid target");return value;}
  static void SetParameterValue(Parameter p,StorageType storage,object value){p.Value=value;if(p.Element.Document.OnWrite!=null)p.Element.Document.OnWrite();}
 }
 class BatchFilterPreviewPeerProgram {
  static int checks;static void Check(bool ok,string label){if(!ok)throw new Exception(label);checks++;Console.WriteLine("PASS " + label);}static void Reject(Action f,string label){try{f();}catch(InvalidOperationException){checks++;Console.WriteLine("PASS " + label);return;}throw new Exception("Expected rejection: "+label);}
  static object Prop(object o,string key){return o.GetType().GetProperty(key).GetValue(o,null);}
  static Document Doc(int count=3){var d=new Document();var cat=Category.GetCategory(d,BuiltInCategory.OST_Walls);d.Elements[10]=new ElementType{Id=new ElementId(10),Category=cat,Document=d};d.Elements[20]=new Level{Id=new ElementId(20),Document=d};for(int i=0;i<count;i++){long id=100+i;var e=new Element{Id=new ElementId(id),UniqueId="uid-"+id,Category=cat,TypeId=new ElementId(10),LevelId=new ElementId(20),Document=d};e.Parameters.Add(new Parameter{Id=new ElementId(-100),Element=e,StorageType=StorageType.String,Value="old-"+id});d.Elements[id]=e;}return d;}
  static object Preview(Document d,long? type=10,long? level=20){return WorkbenchActions.PreviewBatchParameterFilter(d,"OST_Walls",type,level,-100);}
  static void Main(){var d=Doc();var value=Preview(d);var rows=(object[])Prop(value,"items");Check((bool)Prop(value,"complete")&&(int)Prop(value,"total")==3&&(int)Prop(value,"scanned")==3,"complete bounded instance preview");Check((string)Prop(rows[0],"element_id")=="100"&&(string)Prop(rows[2],"element_id")=="102"&&(string)Prop(rows[0],"value_internal")=="old-100","sorted exact identities and raw values");Check((string)Prop(value,"write_authorization")=="not_granted","preview grants no write authority");
   d=Doc(51);Reject(()=>Preview(d),"over 50 matching elements rejects entire preview");d=Doc();d.Elements[100].Parameters[0].IsReadOnly=true;Reject(()=>Preview(d),"read-only target rejects all");d=Doc();d.Elements[100].Parameters.Clear();Reject(()=>Preview(d),"missing parameter rejects all");d=Doc();d.Elements[100].Parameters[0].Element=d.Elements[101];Reject(()=>Preview(d),"wrong owner rejects all");d=Doc();d.Elements[100].Parameters[0].StorageType=StorageType.ElementId;Reject(()=>Preview(d),"non-scalar parameter rejected");d=Doc();d.Elements[101].UniqueId=d.Elements[100].UniqueId;Reject(()=>Preview(d),"duplicate UniqueId rejected");d=Doc();Reject(()=>WorkbenchActions.PreviewBatchParameterFilter(d,"Walls",10,20,-100),"ambiguous display category rejected");Reject(()=>Preview(d,20,20),"wrong type identity rejected");Reject(()=>Preview(d,10,10),"wrong level identity rejected");d=Doc(0);Check((int)Prop(Preview(d),"total")==0,"empty complete match is explicit");Console.WriteLine("PASS total="+checks);
  }
 }
}

class CandidatePeerProgram {
 static int count;static void Check(bool v,string n){if(!v)throw new Exception(n);count++;Console.WriteLine("PASS "+n);}static void Reject(Action a,string n){try{a();}catch(InvalidOperationException){count++;Console.WriteLine("PASS "+n);return;}throw new Exception("Expected rejection: "+n);}
 static Autodesk.Revit.DB.Document Doc(){var d=new Autodesk.Revit.DB.Document();var c=Autodesk.Revit.DB.Category.GetCategory(d,Autodesk.Revit.DB.BuiltInCategory.OST_Walls);for(int i=0;i<2;i++){long id=100+i;var e=new Autodesk.Revit.DB.Element{Id=new Autodesk.Revit.DB.ElementId(id),UniqueId="u"+id,Category=c,Document=d};e.Parameters.Add(new Autodesk.Revit.DB.Parameter{Id=new Autodesk.Revit.DB.ElementId(-100),Element=e,StorageType=Autodesk.Revit.DB.StorageType.String,Value="old"});d.Elements[id]=e;}return d;}
 static object Preview(Autodesk.Revit.DB.Document d){return RevitLocalCodex.WorkbenchActions.PreviewBatchParameterFilter(d,"OST_Walls",null,null,-100);}
 static void Run(Autodesk.Revit.DB.Document d,object snapshot,string mode,Action permission=null){RevitLocalCodex.WorkbenchActions.ExecuteBatchFilterCandidate(d,"OST_Walls",null,null,-100,"String",null,"new",mode,snapshot,permission ?? (()=>{}));}
 static void Main(){var d=Doc();var before=Preview(d);Run(d,before,"commit");Check((string)d.Elements[100].Parameters[0].Value=="new"&&(string)d.Elements[101].Parameters[0].Value=="new","actual producer and candidate commit");d=Doc();before=Preview(d);Run(d,before,"rollback");Check((string)d.Elements[100].Parameters[0].Value=="old","group rollback restores prior values");d=Doc();before=Preview(d);d.OnRegenerate=()=>d.Elements[101].Parameters[0].Value="drift";Reject(()=>Run(d,before,"commit"),"regeneration drift rejected");Check((string)d.Elements[100].Parameters[0].Value=="old"&&(string)d.Elements[101].Parameters[0].Value=="old","drift rolls back group");d=Doc();before=Preview(d);d.Elements[101].UniqueId="different";Reject(()=>Run(d,before,"commit"),"producer identity drift rejected");Check((string)d.Elements[100].Parameters[0].Value=="old","identity drift performs no write");d=Doc();before=Preview(d);Reject(()=>Run(d,before,"commit",()=>{throw new InvalidOperationException("revoked");}),"revoked after preparation blocks before write");Check((string)d.Elements[100].Parameters[0].Value=="old","prewrite revocation preserves original");d=Doc();before=Preview(d);bool revoked=false;d.OnWrite=()=>revoked=true;Reject(()=>Run(d,before,"commit",()=>{if(revoked)throw new InvalidOperationException("revoked");}),"revoked after write blocks commit");Check((string)d.Elements[100].Parameters[0].Value=="old"&&(string)d.Elements[101].Parameters[0].Value=="old","postwrite revocation rolls back group");d=Doc();before=Preview(d);revoked=false;d.OnRegenerate=()=>revoked=true;Reject(()=>Run(d,before,"commit",()=>{if(revoked)throw new InvalidOperationException("revoked");}),"revoked before outer commit blocks commit");Check((string)d.Elements[100].Parameters[0].Value=="old","precommit revocation rolls back group");d=Doc();before=Preview(d);revoked=false;d.OnWrite=()=>revoked=true;d.FailRollback=true;Reject(()=>Run(d,before,"commit",()=>{if(revoked)throw new InvalidOperationException("revoked");}),"rollback failure propagates without success");Check((string)d.Elements[100].Parameters[0].Value=="new","rollback failure leaves outcome unconfirmed");Console.WriteLine("PASS total="+count);}
}
